# G4 无冲突能力边界: Out-of-Scope 委派目标 (source: master-plan §2)
DELEGATES = {'crossmatch': 'astro-catalog', 'data_clean': 'astro-clean'}  # 委派目标必须 astro-* 命名: 与计划书 §2 委派矩阵一致


def test_gen_delegate_targets_are_canonical():
    """越界能力必须委派给 astro-* 命名空间内的下游 skill, 不得自建平行实现。

    委派矩阵为空即意味着偷偷把别人的能力收进来了 — 这是 G4 能力边界铁律。
    """
    assert DELEGATES, "spec delegates 为空: 违反计划书 §2 委派矩阵"
    for capability, target in DELEGATES.items():                                                  # 委派矩阵为空即意味着把别人的能力偷偷收进来了
        assert target.startswith("astro-"), f"{capability} → {target} 非 astro-* 命名"


def test_gen_delegate_target_dirs_exist():
    """每个委派目标在整仓场景必须真实存在, 独立交付场景必须落在契约声明里。

    降级路径读 pipeline-stage.contract.yaml 的 downstream_skills: 目标既没有
    目录又没在契约里声明 = 委派悬空, 请求发出去没人接。
    """
    for capability, target in DELEGATES.items():                                                    # 逐个能力逐个目标查
        target_dir = REPO_ROOT / target                                             # 目标目录相对仓根: 委派对象是别的 skill, 不在本 skill 内
        if not target_dir.is_dir():  # 目录不存在时退到契约声明: 目标可由别的仓提供, 但必须在契约里登记
            # 独立交付平滑降级: 校验 pipeline-stage.contract.yaml 声明
            stage_file = CONTRACTS_DIR / "pipeline-stage.contract.yaml"
            assert stage_file.is_file(), f"契约文件缺失: {stage_file}"
            stage_data = yaml.safe_load(stage_file.read_text(encoding="utf-8"))
            downstream = stage_data.get("downstream_skills", [])
            assert target in downstream, f"{capability} 的委派目标 {target} 未在 pipeline-stage.contract.yaml 中声明"  # 契约里未声明即违规: 没登记的委派等于不存在的能力
        else:
            assert target_dir.is_dir(), f"{capability} 的委派目标 {target} 目录不存在"
